import { useState } from "react";
import { connectWallet, getContract, getWeb3 } from "./contract";
import "./App.css";

function App() {
  const [account, setAccount] = useState("");
  const [owner, setOwner] = useState("");
  const [auctionCounter, setAuctionCounter] = useState("");
  const [refundAmount, setRefundAmount] = useState("0");

  const [title, setTitle] = useState("");
  const [startPrice, setStartPrice] = useState("");
  const [duration, setDuration] = useState("");

  const [auctions, setAuctions] = useState([]);
  const [bidAmounts, setBidAmounts] = useState({});

  const getErrorMessage = (error) => {
    return error.message || error.data?.message || "Transaction failed";
  };

  const updateRefundAmount = async (walletAddress) => {
    try {
      if (!walletAddress) return;

      const web3 = getWeb3();
      const contract = await getContract();

      const refund = await contract.methods
        .pendingReturns(walletAddress)
        .call();

      setRefundAmount(web3.utils.fromWei(refund.toString(), "ether"));
    } catch (error) {
      console.error(error);
    }
  };

  const handleConnect = async () => {
    try {
      const connectedAccount = await connectWallet();

      if (!connectedAccount) return;

      setAccount(connectedAccount);

      const web3 = getWeb3();
      const contract = await getContract();

      const ownerAddress = await contract.methods.owner().call();
      const counter = await contract.methods.auctionCounter().call();
      const refund = await contract.methods
        .pendingReturns(connectedAccount)
        .call();

      setOwner(ownerAddress);
      setAuctionCounter(counter.toString());
      setRefundAmount(web3.utils.fromWei(refund.toString(), "ether"));
    } catch (error) {
      console.error(error);
      alert(getErrorMessage(error));
    }
  };

  const handleCreateAuction = async () => {
    try {
      if (!account) {
        alert("Connect wallet first");
        return;
      }

      if (!title || !startPrice || !duration) {
        alert("Fill all auction fields");
        return;
      }

      const web3 = getWeb3();
      const contract = await getContract();

      const fee = await contract.methods.auctionFee().call();

      await contract.methods
        .createAuction(
          title,
          web3.utils.toWei(startPrice.toString(), "ether"),
          duration.toString()
        )
        .send({
          from: account,
          value: fee,
          gas: "1000000",
        });

      alert("Auction created!");

      setTitle("");
      setStartPrice("");
      setDuration("");

      await loadAuctions();
      await updateRefundAmount(account);
    } catch (error) {
      console.error("Create auction error:", error);
      alert(getErrorMessage(error));
    }
  };

  const loadAuctions = async () => {
    try {
      const web3 = getWeb3();
      const contract = await getContract();

      const counter = await contract.methods.auctionCounter().call();
      const loadedAuctions = [];

      for (let i = 0; i < Number(counter); i++) {
        const auction = await contract.methods.auctions(i).call();

        loadedAuctions.push({
          id: auction.id.toString(),
          title: auction.title,
          seller: auction.seller,
          startPrice: web3.utils.fromWei(
            auction.startPrice.toString(),
            "ether"
          ),
          highestBid: web3.utils.fromWei(
            auction.highestBid.toString(),
            "ether"
          ),
          highestBidder: auction.highestBidder,
          endBlock: auction.endBlock.toString(),
          state:
            auction.state.toString() === "0"
              ? "ACTIVE"
              : auction.state.toString() === "1"
              ? "CANCELLED"
              : "COMPLETED",
        });
      }

      setAuctions(loadedAuctions);
      setAuctionCounter(counter.toString());

      await updateRefundAmount(account);
    } catch (error) {
      console.error(error);
      alert(getErrorMessage(error));
    }
  };

  const placeBid = async (auctionId) => {
    try {
      if (!account) {
        alert("Connect wallet first");
        return;
      }

      const amount = bidAmounts[auctionId];

      if (!amount || Number(amount) <= 0) {
        alert("Enter bid amount in ETH");
        return;
      }

      const web3 = getWeb3();
      const contract = await getContract();

      await contract.methods.bid(auctionId).send({
        from: account,
        value: web3.utils.toWei(amount.toString(), "ether"),
        gas: "300000",
      });

      alert("Bid placed!");

      setBidAmounts({
        ...bidAmounts,
        [auctionId]: "",
      });

      await loadAuctions();
      await updateRefundAmount(account);
    } catch (error) {
      console.error(error);
      alert(getErrorMessage(error));
    }
  };

  const finalizeAuction = async (auctionId) => {
    try {
      if (!account) {
        alert("Connect wallet first");
        return;
      }

      const contract = await getContract();

      await contract.methods.finalizeAuction(auctionId).send({
        from: account,
        gas: "300000",
      });

      alert("Auction finalized!");

      await loadAuctions();
      await updateRefundAmount(account);
    } catch (error) {
      console.error(error);
      alert(getErrorMessage(error));
    }
  };

  const claimRefund = async () => {
    try {
      if (!account) {
        alert("Connect wallet first");
        return;
      }

      const contract = await getContract();

      await contract.methods.claim().send({
        from: account,
        gas: "300000",
      });

      alert("Refund claimed!");

      await loadAuctions();
      await updateRefundAmount(account);
    } catch (error) {
      console.error(error);
      alert(getErrorMessage(error));
    }
  };

  return (
    <div style={{ padding: "20px" }}>
      <h1>Auction Platform</h1>

      <button onClick={handleConnect}>Connect Wallet</button>

      <button onClick={loadAuctions} style={{ marginLeft: "10px" }}>
        Load Auctions
      </button>

      <button onClick={claimRefund} style={{ marginLeft: "10px" }}>
        Claim Refund
      </button>

      <p>Connected account: {account}</p>
      <p>Owner: {owner}</p>
      <p>Auctions: {auctionCounter}</p>
      <p>Available Refund: {refundAmount} ETH</p>

      <hr />

      <h2>Create Auction</h2>

      <input
        type="text"
        placeholder="Title"
        value={title}
        onChange={(e) => setTitle(e.target.value)}
      />

      <br />
      <br />

      <input
        type="text"
        placeholder="Start Price ETH"
        value={startPrice}
        onChange={(e) => setStartPrice(e.target.value)}
      />

      <br />
      <br />

      <input
        type="number"
        placeholder="Duration Blocks"
        value={duration}
        onChange={(e) => setDuration(e.target.value)}
      />

      <br />
      <br />

      <button onClick={handleCreateAuction}>Create Auction</button>

      <hr />

      <h2>Auctions List</h2>

      {auctions.map((auction) => (
        <div key={auction.id} className="auction-card">
          <h3>Auction #{auction.id}</h3>

          <p>Title: {auction.title}</p>
          <p>Seller: {auction.seller}</p>
          <p>Start Price: {auction.startPrice} ETH</p>
          <p>Highest Bid: {auction.highestBid} ETH</p>
          <p>Highest Bidder: {auction.highestBidder}</p>
          <p>End Block: {auction.endBlock}</p>

          <p>
            State:{" "}
            <span
              className={
                auction.state === "ACTIVE"
                  ? "status-active"
                  : auction.state === "COMPLETED"
                  ? "status-completed"
                  : "status-cancelled"
              }
            >
              {auction.state}
            </span>
          </p>

          <input
            type="text"
            placeholder="Bid amount ETH"
            value={bidAmounts[auction.id] || ""}
            onChange={(e) =>
              setBidAmounts({
                ...bidAmounts,
                [auction.id]: e.target.value,
              })
            }
          />

          <button
            onClick={() => placeBid(auction.id)}
            style={{ marginLeft: "10px" }}
          >
            Place Bid
          </button>

          <button
            onClick={() => finalizeAuction(auction.id)}
            style={{ marginLeft: "10px" }}
          >
            Finalize Auction
          </button>

          <hr />
        </div>
      ))}
    </div>
  );
}

export default App;